import { useEffect, useMemo, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { ArrowRight, BookOpen, CalendarDays, Check, ChevronDown, CircleAlert, CircleCheck, GraduationCap, History, Landmark, Plus, Search, ShieldCheck, UserRound, Users, X } from 'lucide-react';
import {
  AcademicAdjustmentInputKind, AcademicDepartureInputKind, PromotionDecisionInputDecision,
  getGetAcademicDashboardQueryKey, getGetStudentAcademicHistoryQueryKey, getGetTermFeeStatementQueryKey,
  getListAcademicEnrollmentsQueryKey, getListAcademicTermFeeSchedulesQueryKey, getListAcademicYearsQueryKey, getListPaymentsQueryKey, getListPromotionDecisionsQueryKey,
  getListStudentsQueryKey, useAllocateExistingAcademicPayment, useCloseAcademicTerm, useConfirmPromotionCycle, useCreateAcademicAdjustment,
  useCreateAcademicEnrollment, useCreateAcademicFeeCharge, useCreateAcademicYear, useCreatePromotionCycle,
  useGetAcademicDashboard, useGetCurrentUser, useGetStudentAcademicHistory, useGetTermFeeStatement,
  useImportCurrentEnrollments, useListAcademicEnrollments, useListAcademicTermFeeSchedules, useListAcademicYears, useListPayments, useListPromotionDecisions,
  useListStudents, useOpenAcademicTerm, useRecordAcademicDeparture, useRecordAcademicPayment, useUpsertAcademicTermFeeSchedule,
  useUpdateAcademicTerm, useUpdatePromotionDecision,
} from '@workspace/api-client-react';
import { AppShell, Button, EmptyState, ErrorState, PageHeader, Panel, Skeleton } from '@/components/school-shell';

type Row = Record<string, unknown>;
type Tab = 'year' | 'pupils' | 'fees' | 'promotion' | 'history';
const asRow = (value: unknown): Row => value && typeof value === 'object' && !Array.isArray(value) ? value as Row : {};
const asRows = (value: unknown): Row[] => Array.isArray(value) ? value.map(asRow) : [];
const str = (value: unknown): string => value == null ? '' : String(value);
const num = (value: unknown): number => Number(value || 0);
const money = (value: unknown): string => `UGX ${new Intl.NumberFormat('en-UG', { maximumFractionDigits: 0 }).format(num(value))}`;
const date = (value: unknown): string => value ? new Date(str(value)).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : '—';
const today = () => new Date().toISOString().slice(0, 10);
const freshKey = () => crypto.randomUUID();
const errorMessage = (error: unknown) => {
  const data = error && typeof error === 'object' && 'data' in error
    ? (error as { data?: unknown }).data
    : undefined;
  const message = data && typeof data === 'object' && 'error' in data
    ? (data as { error?: unknown }).error
    : undefined;
  return typeof message === 'string' ? message : error instanceof Error ? error.message : 'The request could not be completed. Please try again.';
};
const classes = ['Daycare', 'Baby Class', 'Middle Class', 'Top Class', 'Primary 1', 'Primary 2', 'Primary 3', 'Primary 4', 'Primary 5', 'Primary 6', 'Primary 7'];
const fieldClass = 'min-h-10 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3 py-2 text-sm text-[hsl(var(--foreground))] outline-none transition-colors focus:border-[hsl(var(--primary))]';
const labelClass = 'mb-1.5 block text-[11px] font-bold uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))]';
const tabDetails: { id: Tab; title: string; icon: typeof CalendarDays }[] = [
  { id: 'year', title: 'Years & terms', icon: CalendarDays },
  { id: 'pupils', title: 'Enrollments', icon: Users },
  { id: 'fees', title: 'Term accounts', icon: Landmark },
  { id: 'promotion', title: 'Promotion desk', icon: GraduationCap },
  { id: 'history', title: 'Pupil history', icon: History },
];

function Field({ label, children }: { label: string; children: ReactNode }) {
  return <label className="block min-w-0"><span className={labelClass}>{label}</span>{children}</label>;
}

function ConfirmDialog({ title, description, busy, onCancel, onConfirm }: { title: string; description: string; busy: boolean; onCancel: () => void; onConfirm: () => void }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#102c43]/65 p-4" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget && !busy) onCancel(); }}>
    <div role="alertdialog" aria-modal="true" aria-labelledby="academic-confirm-title" aria-describedby="academic-confirm-description" className="w-full max-w-md rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 shadow-2xl">
      <div className="mb-5 flex size-11 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><ShieldCheck size={21} /></div>
      <h2 id="academic-confirm-title" className="font-display text-2xl font-semibold">{title}</h2>
      <p id="academic-confirm-description" className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{description}</p>
      <div className="mt-6 flex justify-end gap-2"><Button variant="secondary" onClick={onCancel} disabled={busy} testId="button-cancel-confirmation">Go back</Button><Button onClick={onConfirm} disabled={busy} testId="button-confirm-academic-action">{busy ? 'Working…' : 'Confirm action'}</Button></div>
    </div>
  </div>;
}

function TermRow({ term, year, canManage, busy, onOpen, onSaveDates, onClose, onError }: {
  term: Row; year: string; canManage: boolean; busy: boolean;
  onOpen: (startsOn: string, endsOn: string) => void; onSaveDates: (startsOn: string, endsOn: string) => void;
  onClose: () => void; onError: (message: string) => void;
}) {
  const [startsOn, setStartsOn] = useState(str(term.startsOn).slice(0, 10));
  const [endsOn, setEndsOn] = useState(str(term.endsOn).slice(0, 10));
  const planned = term.status === 'planned';
  useEffect(() => {
    setStartsOn(str(term.startsOn).slice(0, 10));
    setEndsOn(str(term.endsOn).slice(0, 10));
  }, [term.startsOn, term.endsOn]);
  return <div className="flex flex-col gap-3 p-5 sm:px-6">
    <div className="flex items-center gap-4"><span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] font-mono-ui text-sm font-bold text-[hsl(var(--primary))]">{str(term.number).padStart(2, '0')}</span><div><p className="font-semibold">Term {str(term.number)} · {year}</p><p className="text-xs text-[hsl(var(--muted-foreground))]">Status: <span className="capitalize" data-testid={`status-term-${str(term.id)}`}>{str(term.status)}</span>{Boolean(term.startsOn) && ` · ${date(term.startsOn)}–${date(term.endsOn)}`}</p></div></div>
    {canManage && planned && <form className="grid gap-3 pl-0 sm:grid-cols-[1fr_1fr_auto] sm:items-end sm:pl-14" onSubmit={(event) => {
      event.preventDefault();
      if (!startsOn || !endsOn) { onError('Enter both the start date and end date before opening this term.'); return; }
      if (startsOn > endsOn) { onError('The term start date must be on or before the end date.'); return; }
      onOpen(startsOn, endsOn);
    }}><Field label="Starts on"><input type="date" className={fieldClass} value={startsOn} onChange={(event) => setStartsOn(event.target.value)} required data-testid={`input-term-start-${str(term.id)}`} /></Field><Field label="Ends on"><input type="date" className={fieldClass} value={endsOn} onChange={(event) => setEndsOn(event.target.value)} required data-testid={`input-term-end-${str(term.id)}`} /></Field><div className="flex flex-wrap gap-2"><Button type="button" variant="secondary" disabled={busy || !startsOn || !endsOn || startsOn > endsOn || (startsOn === str(term.startsOn).slice(0, 10) && endsOn === str(term.endsOn).slice(0, 10))} onClick={() => onSaveDates(startsOn, endsOn)} testId={`button-save-term-dates-${str(term.id)}`}>Save dates</Button><Button type="submit" disabled={busy} testId={`button-open-term-${str(term.id)}`}>Open term</Button></div></form>}
    {canManage && term.status === 'open' && <div className="sm:pl-14"><Button variant="secondary" disabled={busy} onClick={onClose} testId={`button-close-term-${str(term.id)}`}>Close term</Button></div>}
  </div>;
}

export default function AcademicPage() {
  const queryClient = useQueryClient();
  const user = useGetCurrentUser();
  const canManage = ['administrator', 'super_admin'].includes(str(user.data?.user.role));
  const canRecordPayment = canManage || user.data?.user.role === 'accountant';
  const [tab, setTab] = useState<Tab>('year');
  const yearsQuery = useListAcademicYears();
  const years = asRows(yearsQuery.data);
  const [selectedYearId, setSelectedYearId] = useState('');
  const year = years.find((item) => str(item.id) === selectedYearId) ?? years.find((item) => item.status === 'current') ?? years[0];
  const yearId = str(year?.id);
  const terms = asRows(year?.terms);
  const [selectedTermId, setSelectedTermId] = useState('');
  const term = terms.find((item) => str(item.id) === selectedTermId) ?? terms.find((item) => item.status === 'open') ?? terms[0];
  const termId = str(term?.id);
  const [scheduleTermId, setScheduleTermId] = useState('');
  const scheduleTerm = terms.find((item) => str(item.id) === scheduleTermId) ?? terms.find((item) => item.status === 'planned') ?? terms[0];
  const scheduleId = str(scheduleTerm?.id);
  const schedulesQuery = useListAcademicTermFeeSchedules(scheduleId, { query: { enabled: !!scheduleId, queryKey: getListAcademicTermFeeSchedulesQueryKey(scheduleId) } });
  const dashboard = useGetAcademicDashboard(yearId ? { academicYearId: yearId } : undefined, { query: { enabled: !!yearId, queryKey: getGetAcademicDashboardQueryKey(yearId ? { academicYearId: yearId } : undefined) } });
  const enrollmentsQuery = useListAcademicEnrollments(yearId, { query: { enabled: !!yearId, queryKey: getListAcademicEnrollmentsQueryKey(yearId) } });
  const statementQuery = useGetTermFeeStatement(termId, { query: { enabled: !!termId, queryKey: getGetTermFeeStatementQueryKey(termId) } });
  const paymentsQuery = useListPayments({ query: { enabled: canRecordPayment && tab === 'fees', queryKey: getListPaymentsQueryKey() } });
  const studentsQuery = useListStudents(undefined, { query: { enabled: canManage, queryKey: getListStudentsQueryKey(undefined) } });
  const enrollments = asRows(enrollmentsQuery.data);
  const statement = asRow(statementQuery.data);
  const chargeRows = asRows(statement.rows);
  const summary = asRow(dashboard.data);
  const [localCycle, setLocalCycle] = useState<Row | null>(null);
  const currentCycle = localCycle && str(localCycle.fromYearId) === yearId ? localCycle : {};
  const cycleId = str(currentCycle.id);
  const decisionsQuery = useListPromotionDecisions(cycleId, { query: { enabled: !!cycleId, queryKey: getListPromotionDecisionsQueryKey(cycleId) } });
  const decisions = asRows(decisionsQuery.data);
  const [historyId, setHistoryId] = useState('');
  const historyQuery = useGetStudentAcademicHistory(historyId, { query: { enabled: !!historyId, queryKey: getGetStudentAcademicHistoryQueryKey(historyId) } });

  const createYear = useCreateAcademicYear();
  const importPupils = useImportCurrentEnrollments();
  const createEnrollment = useCreateAcademicEnrollment();
  const openTerm = useOpenAcademicTerm();
  const closeTerm = useCloseAcademicTerm();
  const updateTerm = useUpdateAcademicTerm();
  const createCharge = useCreateAcademicFeeCharge();
  const recordPayment = useRecordAcademicPayment();
  const allocateExistingPayment = useAllocateExistingAcademicPayment();
  const upsertSchedule = useUpsertAcademicTermFeeSchedule();
  const createAdjustment = useCreateAcademicAdjustment();
  const recordDeparture = useRecordAcademicDeparture();
  const createCycle = useCreatePromotionCycle();
  const updateDecision = useUpdatePromotionDecision();
  const confirmCycle = useConfirmPromotionCycle();

  const [notice, setNotice] = useState<{ kind: 'success' | 'error'; text: string } | null>(null);
  const [pending, setPending] = useState<{ title: string; description: string; action: () => Promise<void> } | null>(null);
  const [busy, setBusy] = useState(false);
  const [newYear, setNewYear] = useState(String(new Date().getFullYear()));
  const [scheduleClass, setScheduleClass] = useState('');
  const [scheduleStream, setScheduleStream] = useState('');
  const [scheduleEnrollmentType, setScheduleEnrollmentType] = useState('day');
  const [scheduleCategory, setScheduleCategory] = useState('Tuition');
  const [scheduleAmount, setScheduleAmount] = useState('');
  const [scheduleDescription, setScheduleDescription] = useState('');
  const [legacyPaymentId, setLegacyPaymentId] = useState('');
  const [legacyChargeId, setLegacyChargeId] = useState('');
  const [legacyAmount, setLegacyAmount] = useState('');
  const [pupilId, setPupilId] = useState('');
  const [className, setClassName] = useState('');
  const [stream, setStream] = useState('');
  const [enrolledOn, setEnrolledOn] = useState(today());
  const [search, setSearch] = useState('');
  const [chargeEnrollment, setChargeEnrollment] = useState('');
  const [category, setCategory] = useState('Tuition');
  const [chargeAmount, setChargeAmount] = useState('');
  const [chargeDescription, setChargeDescription] = useState('');
  const [activeCharge, setActiveCharge] = useState('');
  const [paymentAmount, setPaymentAmount] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('Cash');
  const [paymentReference, setPaymentReference] = useState('');
  const [adjustmentKind, setAdjustmentKind] = useState<keyof typeof AcademicAdjustmentInputKind>('waiver');
  const [adjustmentAmount, setAdjustmentAmount] = useState('');
  const [adjustmentReason, setAdjustmentReason] = useState('');
  const [departureId, setDepartureId] = useState('');
  const [departureKind, setDepartureKind] = useState<keyof typeof AcademicDepartureInputKind>('transferred');
  const [departureDate, setDepartureDate] = useState(today());
  const [departureReason, setDepartureReason] = useState('');
  const [destination, setDestination] = useState('');
  const [editingDecision, setEditingDecision] = useState('');
  const [decisionType, setDecisionType] = useState<keyof typeof PromotionDecisionInputDecision>('hold');
  const [nextClass, setNextClass] = useState('');
  const [nextStream, setNextStream] = useState('');
  const [decisionNote, setDecisionNote] = useState('');

  const invalidate = async () => {
    await Promise.all([
      queryClient.invalidateQueries({ queryKey: getListAcademicYearsQueryKey() }),
      queryClient.invalidateQueries({ queryKey: getGetAcademicDashboardQueryKey(yearId ? { academicYearId: yearId } : undefined) }),
      queryClient.invalidateQueries({ queryKey: getListStudentsQueryKey(undefined) }),
      ...(yearId ? [queryClient.invalidateQueries({ queryKey: getListAcademicEnrollmentsQueryKey(yearId) })] : []),
      ...(termId ? [queryClient.invalidateQueries({ queryKey: getGetTermFeeStatementQueryKey(termId) })] : []),
      ...(scheduleId ? [queryClient.invalidateQueries({ queryKey: getListAcademicTermFeeSchedulesQueryKey(scheduleId) })] : []),
      queryClient.invalidateQueries({ queryKey: getListPaymentsQueryKey() }),
      ...(cycleId ? [queryClient.invalidateQueries({ queryKey: getListPromotionDecisionsQueryKey(cycleId) })] : []),
      ...(historyId ? [queryClient.invalidateQueries({ queryKey: getGetStudentAcademicHistoryQueryKey(historyId) })] : []),
    ]);
  };
  const execute = async (action: () => Promise<unknown>, success: string, after?: (result: unknown) => void, permission: 'admin' | 'payment' = 'admin') => {
    if ((permission === 'payment' ? !canRecordPayment : !canManage) || busy) return;
    setBusy(true); setNotice(null);
    try {
      const result = await action();
      await invalidate();
      setNotice({ kind: 'success', text: success });
      after?.(result);
    } catch (error) {
      setNotice({ kind: 'error', text: errorMessage(error) });
    } finally { setBusy(false); }
  };
  const requestConfirmation = (title: string, description: string, action: () => Promise<void>) => setPending({ title, description, action });
  const filteredEnrollments = useMemo(() => enrollments.filter((item) => `${str(item.studentName)} ${str(item.registrationNumber)} ${str(item.className)}`.toLowerCase().includes(search.toLowerCase())), [enrollments, search]);
  const unenrolledPupils = useMemo(() => (studentsQuery.data ?? []).filter((item) => !enrollments.some((enrollment) => str(enrollment.studentId) === item.id)), [studentsQuery.data, enrollments]);
  const unassignedReceipts = useMemo(() => (paymentsQuery.data ?? []).filter((payment) => payment.status === 'completed' && payment.attributionStatus === 'unassigned' && num(payment.amount) > (payment.academicAllocations ?? []).reduce((sum, allocation) => sum + num(allocation.amount), 0)), [paymentsQuery.data]);
  const selectedReceipt = unassignedReceipts.find((item) => item.id === legacyPaymentId);
  const unallocatedAmount = selectedReceipt ? Math.max(0, num(selectedReceipt.amount) - (selectedReceipt.academicAllocations ?? []).reduce((sum, item) => sum + num(item.amount), 0)) : 0;
  const matchingCharges = chargeRows.filter((row) => str(row.studentId) === selectedReceipt?.studentId && num(row.outstanding) > 0);
  useEffect(() => { setSelectedTermId(''); setScheduleTermId(''); setLocalCycle(null); setHistoryId(''); }, [yearId]);
  useEffect(() => { setActiveCharge(''); setLegacyChargeId(''); }, [termId]);
  const formSubmit = (event: FormEvent, action: () => void) => { event.preventDefault(); action(); };
  const loadingBlock = <div className="space-y-3 p-5"><Skeleton className="h-12 w-full" /><Skeleton className="h-12 w-4/5" /><Skeleton className="h-12 w-3/5" /></div>;
  const sectionTitle = (eyebrow: string, title: string, detail: string) => <div className="mb-5"><p className="font-mono-ui text-[10px] font-bold uppercase tracking-[.2em] text-[hsl(var(--primary))]">{eyebrow}</p><h2 className="mt-1 font-display text-2xl font-semibold tracking-tight">{title}</h2><p className="mt-1 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{detail}</p></div>;

  return <AppShell><div className="mx-auto max-w-[1400px] pb-16">
    <PageHeader eyebrow="Academic administration / EMMECTY" title="Academic years" description="One continuous record for each pupil: their class, their term, and every shilling paid against its original charge." />
    {user.isLoading || yearsQuery.isLoading ? <Panel>{loadingBlock}</Panel> : yearsQuery.isError ? <ErrorState onRetry={() => void yearsQuery.refetch()} message={errorMessage(yearsQuery.error)} /> : <>
      <div className="mb-6 flex flex-col gap-4 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--secondary)/.55)] p-4 sm:flex-row sm:items-center sm:justify-between sm:p-5">
        <div className="flex items-center gap-3"><span className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]"><BookOpen size={21} /></span><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-[hsl(var(--muted-foreground))]">Working register</p><p className="font-display text-xl font-semibold" data-testid="text-selected-academic-year">{year ? `${str(year.year)} academic year` : 'No year selected'}</p></div></div>
        <div className="flex flex-wrap items-end gap-3"><Field label="Academic year"><select className={fieldClass} value={yearId} onChange={(event) => setSelectedYearId(event.target.value)} data-testid="select-academic-year"><option value="">Select year</option>{years.map((item) => <option value={str(item.id)} key={str(item.id)}>{str(item.year)} · {str(item.status || 'planned')}</option>)}</select></Field>{!canManage && <span className="rounded-full border border-[hsl(var(--border))] px-3 py-2 text-xs font-semibold text-[hsl(var(--muted-foreground))]" data-testid="status-academic-access">{canRecordPayment ? 'Payments access' : 'Read-only access'}</span>}</div>
      </div>
      {notice && <div role="status" data-testid="status-academic-action" className={`mb-5 flex items-start gap-3 rounded-xl border px-4 py-3 text-sm ${notice.kind === 'error' ? 'border-[#c98076] bg-[#fff1ee] text-[#863c35]' : 'border-[#92b6a2] bg-[#ecf6ed] text-[#235c44]'}`}>{notice.kind === 'error' ? <CircleAlert size={18} className="mt-0.5 shrink-0" /> : <CircleCheck size={18} className="mt-0.5 shrink-0" />}<span className="flex-1">{notice.text}</span><button type="button" onClick={() => setNotice(null)} aria-label="Dismiss notice" data-testid="button-dismiss-academic-notice"><X size={16} /></button></div>}
      <nav aria-label="Academic sections" className="mb-6 flex gap-1 overflow-x-auto border-b border-[hsl(var(--border))] pb-px">{tabDetails.map(({ id, title, icon: Icon }) => <button type="button" key={id} onClick={() => setTab(id)} data-testid={`tab-academic-${id}`} aria-current={tab === id ? 'page' : undefined} className={`flex shrink-0 items-center gap-2 border-b-2 px-4 py-3 text-sm font-semibold transition-colors ${tab === id ? 'border-[hsl(var(--primary))] text-[hsl(var(--primary))]' : 'border-transparent text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]'}`}><Icon size={16} />{title}</button>)}</nav>

      {tab === 'year' && <div className="grid gap-5 xl:grid-cols-[1fr_340px]">
        <div className="space-y-5">
          {year && <Panel className="p-5 sm:p-6">
            {sectionTitle('00 / Fee schedules', 'Prepare charges before opening', 'Every active class, stream and enrollment type needs a matching schedule for this term. Opening creates charges from these schedules; sponsored pupils receive zero-amount charges. No historic payment is assigned automatically.')}
            <div className="mb-4 max-w-xs"><Field label="Term to configure"><select className={fieldClass} value={scheduleId} onChange={(event) => setScheduleTermId(event.target.value)} data-testid="select-schedule-term">{terms.map((item) => <option key={str(item.id)} value={str(item.id)}>Term {str(item.number)} · {str(item.status)}</option>)}</select></Field></div>
            {!scheduleId ? <p className="text-sm text-[hsl(var(--muted-foreground))]">Choose a term to view its schedules.</p> : schedulesQuery.isLoading ? loadingBlock : schedulesQuery.isError ? <ErrorState onRetry={() => void schedulesQuery.refetch()} message="Fee schedules could not be loaded." /> : <div className="space-y-2">
              {(schedulesQuery.data ?? []).length ? (schedulesQuery.data ?? []).map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[hsl(var(--border))] px-4 py-3" data-testid={`row-fee-schedule-${item.id}`}><div><p className="text-sm font-semibold">{item.className}{item.stream ? ` / ${item.stream}` : ''} · {item.enrollmentType || 'Unspecified'} · {item.category}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{item.description || 'No description'}</p></div><div className="flex items-center gap-2"><span className="font-mono-ui text-sm font-semibold">{money(item.amount)}</span>{canManage && scheduleTerm?.status === 'planned' && <Button variant="quiet" onClick={() => { setScheduleClass(item.className); setScheduleStream(item.stream); setScheduleEnrollmentType(item.enrollmentType); setScheduleCategory(item.category); setScheduleAmount(String(item.amount)); setScheduleDescription(item.description); }} testId={`button-edit-fee-schedule-${item.id}`}>Edit</Button>}</div></div>) : <p className="rounded-xl bg-[hsl(var(--secondary)/.5)] px-4 py-3 text-sm text-[hsl(var(--muted-foreground))]">No schedules for this term. Add a schedule for every active class, stream and day/boarding/unspecified enrollment type before opening.</p>}
            </div>}
            {canManage && scheduleTerm?.status === 'planned' && <form className="mt-5 grid gap-3 sm:grid-cols-2" onSubmit={(event) => formSubmit(event, () => {
              const amount = Number(scheduleAmount);
              if (!scheduleClass.trim() || !scheduleCategory.trim() || !scheduleAmount.trim() || !Number.isFinite(amount) || amount < 0) { setNotice({ kind: 'error', text: 'Enter a class, category and a non-negative schedule amount.' }); return; }
              void execute(() => upsertSchedule.mutateAsync({ termId: scheduleId, data: { className: scheduleClass.trim(), stream: scheduleStream.trim(), enrollmentType: scheduleEnrollmentType as '' | 'day' | 'boarding', category: scheduleCategory.trim(), amount, description: scheduleDescription.trim() } }), 'Term fee schedule saved.');
            })}>
              <Field label="Class"><input className={fieldClass} list="academic-schedule-classes" value={scheduleClass} onChange={(event) => setScheduleClass(event.target.value)} required maxLength={120} data-testid="input-schedule-class" /><datalist id="academic-schedule-classes">{classes.map((item) => <option key={item} value={item} />)}</datalist></Field>
              <Field label="Stream (blank if none)"><input className={fieldClass} value={scheduleStream} onChange={(event) => setScheduleStream(event.target.value)} maxLength={120} data-testid="input-schedule-stream" /></Field>
              <Field label="Enrollment type"><select className={fieldClass} value={scheduleEnrollmentType} onChange={(event) => setScheduleEnrollmentType(event.target.value)} data-testid="select-schedule-enrollment-type"><option value="day">Day</option><option value="boarding">Boarding</option><option value="">Unspecified</option></select></Field>
              <Field label="Category"><input className={fieldClass} value={scheduleCategory} onChange={(event) => setScheduleCategory(event.target.value)} required maxLength={120} data-testid="input-schedule-category" /></Field>
              <Field label="Amount (UGX)"><input type="number" min="0" step="0.01" className={fieldClass} value={scheduleAmount} onChange={(event) => setScheduleAmount(event.target.value)} required data-testid="input-schedule-amount" /></Field>
              <Field label="Description"><input className={fieldClass} value={scheduleDescription} onChange={(event) => setScheduleDescription(event.target.value)} maxLength={500} data-testid="input-schedule-description" /></Field>
              <div className="sm:col-span-2"><Button type="submit" disabled={busy || schedulesQuery.isLoading || schedulesQuery.isError} testId="button-save-fee-schedule">Save schedule</Button></div>
            </form>}
          </Panel>}
          {year ? <Panel className="overflow-hidden"><div className="border-b border-[hsl(var(--border))] p-5 sm:p-6">{sectionTitle('01 / Calendar', `${str(year.year)} term ledger`, 'Set dates and complete fee schedules before opening. Closing preserves all original accounts and enrollment history.')}</div><div className="divide-y divide-[hsl(var(--border))]">{terms.map((item) => <TermRow key={str(item.id)} term={item} year={str(year.year)} canManage={canManage} busy={busy} onError={(text) => setNotice({ kind: 'error', text })} onSaveDates={(startsOn, endsOn) => { void execute(() => updateTerm.mutateAsync({ termId: str(item.id), data: { startsOn, endsOn } }), `Term ${str(item.number)} dates saved.`); }} onOpen={(startsOn, endsOn) => requestConfirmation('Open this term and create its charges?', `Open Term ${str(item.number)} from ${date(startsOn)} to ${date(endsOn)}? This creates charges for active pupils from their matching class, stream and enrollment-type schedules. Sponsored pupils receive zero-amount charges. Prior receipts remain unassigned unless you allocate them explicitly.`, async () => { await execute(() => openTerm.mutateAsync({ termId: str(item.id), data: { startsOn, endsOn } }), `Term ${str(item.number)} opened and scheduled charges created.`); })} onClose={() => requestConfirmation('Close this term?', `Close Term ${str(item.number)}? Charges and payments remain attached to this term. Closed terms cannot be reopened.`, async () => { await execute(() => closeTerm.mutateAsync({ termId: str(item.id) }), `Term ${str(item.number)} closed.`); })} />)}</div></Panel> : <Panel><EmptyState icon={CalendarDays} title="Start with an academic year" description="Create a year to establish its three planned terms. Nothing is copied or charged automatically." /></Panel>}
          {year && <Panel className="p-5 sm:p-6">{sectionTitle('02 / At a glance', 'The year in numbers', 'Figures are calculated from this year’s enrolled pupils and term-specific financial records.')}{dashboard.isLoading ? loadingBlock : dashboard.isError ? <ErrorState onRetry={() => void dashboard.refetch()} /> : <div className="grid gap-3 sm:grid-cols-2">{[['Active enrollments', enrollments.filter((item) => item.status === 'active').length, 'Pupils in this year'], ['Awaiting decisions', str(summary.awaitingDecisions ?? 0), 'Promotion review'], ['Former pupil balances', money(summary.formerOutstanding), 'Still owed, not erased'], ['Payments from former pupils', money(summary.formerPayments), 'Preserved in the original term']].map(([name, value, caption]) => <div key={str(name)} className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background)/.65)] p-4"><p className="text-xs text-[hsl(var(--muted-foreground))]">{name}</p><p className="mt-2 font-display text-2xl font-semibold" data-testid={`text-academic-${str(name).toLowerCase().replaceAll(' ', '-')}`}>{value}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{caption}</p></div>)}</div>}</Panel>}
        </div>
        <div className="space-y-5">{canManage && <Panel className="p-5">{sectionTitle('Set up', 'Add an academic year', 'Creates a year with Terms 1, 2 and 3 in planned status.')}<form onSubmit={(event) => formSubmit(event, () => { const value = Number(newYear); if (!Number.isInteger(value) || value < 1900 || value > 2200) { setNotice({ kind: 'error', text: 'Enter a valid year between 1900 and 2200.' }); return; } void execute(() => createYear.mutateAsync({ data: { year: value } }), `${value} academic year is ready.`, (result) => setSelectedYearId(str(asRow(result).id))); })} className="flex gap-2"><input className={fieldClass} type="number" min="1900" max="2200" value={newYear} onChange={(event) => setNewYear(event.target.value)} aria-label="New academic year" data-testid="input-new-academic-year" required /><Button type="submit" disabled={busy} testId="button-create-academic-year"><Plus size={16} /> Create</Button></form></Panel>}
          {canManage && year && <Panel className="p-5">{sectionTitle('Once per register', 'Bring in current pupils', 'Links existing active pupil profiles to this year. It does not create duplicate pupils or import old payments into a term.')}<Button variant="secondary" disabled={busy} onClick={() => requestConfirmation('Import existing pupils?', `Link active pupil profiles to ${str(year.year)} using their current classes? Pupils already enrolled in this year will be left unchanged. Historic payments will not be assigned to any term.`, async () => { await execute(() => importPupils.mutateAsync({ yearId }), 'Import finished. Existing enrollments were left unchanged.', (result) => { const r = asRow(result); setNotice({ kind: 'success', text: `Import finished: ${str(r.created)} linked; ${str(r.unchanged)} already present.` }); }); })} testId="button-import-current-pupils"><Users size={16} /> Import current pupils</Button></Panel>}
          <div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--secondary)/.45)] p-5"><p className="flex items-center gap-2 text-sm font-semibold"><ShieldCheck size={16} /> Record integrity</p><p className="mt-2 text-xs leading-6 text-[hsl(var(--muted-foreground))]">Promotion creates new-year enrollments. Former classes, term charges and receipts stay in the original year. To settle old balances, choose the original charge in its original term.</p></div>
        </div>
      </div>}

      {tab === 'pupils' && <div className="grid gap-5 xl:grid-cols-[1fr_350px]"><Panel className="overflow-hidden"><div className="flex flex-col gap-4 border-b border-[hsl(var(--border))] p-5 sm:flex-row sm:items-end sm:justify-between sm:p-6"><div>{sectionTitle('Register', 'Pupils in this year', 'Current and former enrollments remain visible together.')}</div><div className="relative"><Search size={16} className="absolute left-3 top-3 text-[hsl(var(--muted-foreground))]" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search name, ID or class" className={`${fieldClass} pl-9`} data-testid="input-search-enrollments" /></div></div>{!year ? <EmptyState icon={Users} title="Choose a year" description="Select an academic year to see its enrollments." /> : enrollmentsQuery.isLoading ? loadingBlock : enrollmentsQuery.isError ? <ErrorState onRetry={() => void enrollmentsQuery.refetch()} /> : filteredEnrollments.length ? <div className="divide-y divide-[hsl(var(--border))]">{filteredEnrollments.map((item) => <div key={str(item.id)} data-testid={`row-academic-enrollment-${str(item.id)}`} className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between sm:px-6"><div><p className="font-semibold">{str(item.studentName)}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{str(item.registrationNumber)} · {str(item.className)} {str(item.stream)} · Enrolled {date(item.enrolledOn)}</p></div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-[hsl(var(--secondary))] px-3 py-1 text-xs font-semibold capitalize" data-testid={`status-enrollment-${str(item.id)}`}>{str(item.status)}</span><Button variant="quiet" onClick={() => { setHistoryId(str(item.studentId)); setTab('history'); }} testId={`button-history-${str(item.id)}`}>History <ArrowRight size={15} /></Button>{canManage && item.status === 'active' && <Button variant="secondary" onClick={() => { setDepartureId(str(item.id)); setDepartureReason(''); }} testId={`button-departure-${str(item.id)}`}>Departure</Button>}</div></div>)}</div> : <EmptyState icon={UserRound} title={search ? 'No matching pupils' : 'No enrollments yet'} description={search ? 'Try another name, registration number or class.' : 'Import the active pupil register or enroll an existing pupil profile.'} />}</Panel>
        <div className="space-y-5">{canManage && year && <Panel className="p-5">{sectionTitle('Individual enrollment', 'Add an existing pupil', 'Select a profile already in the pupil directory. This never creates another pupil.')}<form className="space-y-3" onSubmit={(event) => formSubmit(event, () => { if (!pupilId || !className) return; void execute(() => createEnrollment.mutateAsync({ data: { yearId, studentId: pupilId, className, stream, enrolledOn } }), 'Pupil enrolled in this academic year.', () => { setPupilId(''); setClassName(''); setStream(''); }); })}><Field label="Existing pupil"><select className={fieldClass} value={pupilId} onChange={(event) => { const id = event.target.value; setPupilId(id); const pupil = (studentsQuery.data ?? []).find((item) => item.id === id); if (pupil) { setClassName(pupil.className); setStream(pupil.stream); } }} required data-testid="select-existing-pupil"><option value="">Choose a pupil</option>{unenrolledPupils.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.registrationNumber}</option>)}</select></Field><Field label="Class"><select className={fieldClass} value={className} onChange={(event) => setClassName(event.target.value)} required data-testid="select-enrollment-class"><option value="">Choose class</option>{classes.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Stream"><input className={fieldClass} value={stream} onChange={(event) => setStream(event.target.value)} data-testid="input-enrollment-stream" /></Field><Field label="Enrollment date"><input type="date" className={fieldClass} value={enrolledOn} onChange={(event) => setEnrolledOn(event.target.value)} required data-testid="input-enrollment-date" /></Field><Button type="submit" disabled={busy || studentsQuery.isLoading || !unenrolledPupils.length} testId="button-create-enrollment">Enroll existing pupil</Button>{studentsQuery.isError && <p className="text-xs text-[#a04336]">Pupil directory unavailable. <button type="button" onClick={() => void studentsQuery.refetch()} className="underline" data-testid="button-retry-pupils">Retry</button></p>}</form></Panel>}
          {canManage && departureId && <Panel className="p-5">{sectionTitle('Keep the record', 'Record a departure', 'Their earlier class and financial history remain available.')}<form className="space-y-3" onSubmit={(event) => formSubmit(event, () => { if (departureReason.trim().length < 3) return; requestConfirmation(`Record ${departureKind === 'transferred' ? 'transfer' : 'withdrawal'}?`, 'This closes the active enrollment without deleting historic classes, charges, balances or receipts.', async () => { await execute(() => recordDeparture.mutateAsync({ enrollmentId: departureId, data: { kind: AcademicDepartureInputKind[departureKind], leavingOn: departureDate, reason: departureReason.trim(), ...(departureKind === 'transferred' && destination.trim() ? { destinationSchool: destination.trim() } : {}) } }), 'Departure recorded; history remains intact.', () => setDepartureId('')); }); })}><Field label="Departure type"><select className={fieldClass} value={departureKind} onChange={(event) => setDepartureKind(event.target.value as typeof departureKind)} data-testid="select-departure-kind"><option value="transferred">Transferred</option><option value="withdrawn">Withdrawn</option></select></Field><Field label="Leaving date"><input type="date" className={fieldClass} value={departureDate} onChange={(event) => setDepartureDate(event.target.value)} required data-testid="input-departure-date" /></Field><Field label="Reason"><input className={fieldClass} value={departureReason} onChange={(event) => setDepartureReason(event.target.value)} minLength={3} required data-testid="input-departure-reason" /></Field>{departureKind === 'transferred' && <Field label="Destination school"><input className={fieldClass} value={destination} onChange={(event) => setDestination(event.target.value)} data-testid="input-departure-destination" /></Field>}<div className="flex gap-2"><Button type="submit" disabled={busy} testId="button-save-departure">Record departure</Button><Button variant="quiet" onClick={() => setDepartureId('')} testId="button-cancel-departure">Cancel</Button></div></form></Panel>}</div></div>}

      {tab === 'fees' && <div className="space-y-5">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div>{sectionTitle('Term-specific ledger', 'Accounts by original term', 'A payment must be allocated to a selected charge. Earlier balances are shown, not silently moved.')}</div><Field label="View term"><select className={fieldClass} value={termId} onChange={(event) => setSelectedTermId(event.target.value)} data-testid="select-fee-term"><option value="">Choose term</option>{terms.map((item) => <option key={str(item.id)} value={str(item.id)}>Term {str(item.number)} · {str(item.status)}</option>)}</select></Field></div>
        {!canManage && canRecordPayment && termId && !statementQuery.isLoading && !statementQuery.isError && chargeRows.length > 0 && <Panel className="p-5 sm:p-6">
          {sectionTitle('Finance desk', 'Allocate a payment', 'Select an existing charge in this term. Payments stay with the original charge, including charges from earlier years.')}
          <form className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4" onSubmit={(event) => formSubmit(event, () => {
            const amount = Number(paymentAmount);
            if (!activeCharge || !Number.isFinite(amount) || amount <= 0 || !paymentMethod.trim()) return;
            const chargeId = activeCharge;
            const reference = paymentReference.trim();
            const method = paymentMethod.trim();
            requestConfirmation('Record payment against this charge?', `${money(amount)} will be allocated only to the selected charge in Term ${str(term?.number)}. It will not be spread across terms.`, async () => {
              await execute(() => recordPayment.mutateAsync({ chargeId, data: { amount, method, reference, idempotencyKey: freshKey() } }), 'Payment recorded against the selected original charge.', () => {
                setActiveCharge(''); setPaymentAmount(''); setPaymentReference('');
              }, 'payment');
            });
          })}>
            <Field label="Original charge"><select className={fieldClass} value={activeCharge} onChange={(event) => setActiveCharge(event.target.value)} required data-testid="select-accountant-charge"><option value="">Select pupil and charge</option>{chargeRows.map((row) => <option key={str(row.chargeId)} value={str(row.chargeId)}>{str(row.studentName)} · {str(row.category)} · {money(row.outstanding)} due</option>)}</select></Field>
            <Field label="Amount (UGX)"><input className={fieldClass} type="number" min="0.01" step="0.01" value={paymentAmount} onChange={(event) => setPaymentAmount(event.target.value)} required data-testid="input-accountant-payment-amount" /></Field>
            <Field label="Method"><select className={fieldClass} value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value)} data-testid="select-accountant-payment-method"><option>Cash</option><option>Mobile Money</option><option>Bank transfer</option><option>Cheque</option></select></Field>
            <Field label="Reference (optional)"><input className={fieldClass} value={paymentReference} onChange={(event) => setPaymentReference(event.target.value)} data-testid="input-accountant-payment-reference" /></Field>
            <div className="sm:col-span-2 xl:col-span-4"><Button type="submit" disabled={busy || !activeCharge} testId="button-record-accountant-payment">Record against charge</Button></div>
          </form>
        </Panel>}
        {canRecordPayment && termId && <Panel className="p-5 sm:p-6">
          {sectionTitle('Older receipts / deliberate allocation', 'Assign an unassigned receipt', 'Choose the receipt, then a charge belonging to the same pupil in the selected original term. No term is inferred from a receipt date or current class.')}
          {paymentsQuery.isLoading || statementQuery.isLoading ? loadingBlock : paymentsQuery.isError ? <ErrorState onRetry={() => void paymentsQuery.refetch()} message="Receipts could not be loaded." /> : statementQuery.isError ? <ErrorState onRetry={() => void statementQuery.refetch()} message="Term charges could not be loaded." /> : !unassignedReceipts.length ? <p className="text-sm text-[hsl(var(--muted-foreground))]">No completed unassigned receipts are available. Existing assigned receipts remain attached to their original charges.</p> : <form className="grid gap-3 sm:grid-cols-2" onSubmit={(event) => formSubmit(event, () => {
            const amount = Number(legacyAmount);
            const charge = matchingCharges.find((item) => str(item.chargeId) === legacyChargeId);
            if (!selectedReceipt || !charge || !Number.isFinite(amount) || amount <= 0 || amount > unallocatedAmount || amount > num(charge.outstanding)) {
              setNotice({ kind: 'error', text: 'Choose an unassigned receipt and a same-pupil charge, then enter an amount no greater than the unassigned receipt or charge balance.' }); return;
            }
            const paymentId = selectedReceipt.id;
            const chargeId = str(charge.chargeId);
            requestConfirmation('Allocate this older receipt?', `Allocate ${money(amount)} from receipt ${selectedReceipt.receiptNumber} for ${selectedReceipt.studentName} to ${str(charge.category)} in ${str(year?.year)} Term ${str(term?.number)}? Only this chosen original charge will receive the allocation.`, async () => {
              await execute(() => allocateExistingPayment.mutateAsync({ paymentId, data: { chargeId, amount, idempotencyKey: freshKey() } }), 'Older receipt allocated to the selected original term charge.', () => { setLegacyPaymentId(''); setLegacyChargeId(''); setLegacyAmount(''); }, 'payment');
            });
          })}>
            <Field label="Unassigned completed receipt"><select className={fieldClass} value={legacyPaymentId} onChange={(event) => { setLegacyPaymentId(event.target.value); setLegacyChargeId(''); setLegacyAmount(''); }} required data-testid="select-unassigned-receipt"><option value="">Choose receipt</option>{unassignedReceipts.map((payment) => <option key={payment.id} value={payment.id}>{payment.receiptNumber} · {payment.studentName} · {money(payment.amount)} · {payment.date}</option>)}</select></Field>
            <Field label="Same-pupil charge in this term"><select className={fieldClass} value={legacyChargeId} onChange={(event) => setLegacyChargeId(event.target.value)} disabled={!selectedReceipt} required data-testid="select-legacy-target-charge"><option value="">Choose original charge</option>{matchingCharges.map((row) => <option key={str(row.chargeId)} value={str(row.chargeId)}>{str(row.category)} · {str(row.studentName)} · {money(row.outstanding)} due</option>)}</select></Field>
            <Field label={`Amount (UGX) · ${money(unallocatedAmount)} unassigned`}><input className={fieldClass} type="number" min="0.01" max={Math.min(unallocatedAmount, num(matchingCharges.find((item) => str(item.chargeId) === legacyChargeId)?.outstanding || unallocatedAmount))} step="0.01" value={legacyAmount} onChange={(event) => setLegacyAmount(event.target.value)} required disabled={!legacyChargeId} data-testid="input-legacy-allocation-amount" /></Field>
            <div className="flex items-end"><Button type="submit" disabled={busy || !legacyChargeId} testId="button-allocate-older-receipt">Allocate explicitly</Button></div>
            {selectedReceipt && !matchingCharges.length && <p className="sm:col-span-2 text-xs text-[hsl(var(--muted-foreground))]">This pupil has no outstanding charge in this term. Select the original year and term with an unpaid charge before allocating.</p>}
          </form>}
        </Panel>}
        {!termId ? <Panel><EmptyState icon={Landmark} title="Choose a term" description="Select a year and term to inspect its original charges and payments." /></Panel> : statementQuery.isLoading ? <Panel>{loadingBlock}</Panel> : statementQuery.isError ? <ErrorState onRetry={() => void statementQuery.refetch()} /> : <div className="grid gap-5 xl:grid-cols-[1fr_350px]"><Panel className="overflow-hidden"><div className="border-b border-[hsl(var(--border))] p-5 sm:p-6"><p className="font-display text-xl font-semibold">Term {str(term?.number)} statement</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{chargeRows.length} original charge{chargeRows.length === 1 ? '' : 's'} · The carried balance is informational, not a new charge.</p></div>{chargeRows.length ? <div className="divide-y divide-[hsl(var(--border))]">{chargeRows.map((row) => <div key={str(row.chargeId)} data-testid={`row-term-charge-${str(row.chargeId)}`} className="p-5 sm:px-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-semibold">{str(row.studentName)} <span className="font-normal text-[hsl(var(--muted-foreground))]">/ {str(row.category)}</span></p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{str(row.registrationNumber)} · {str(row.className)} {str(row.stream)}</p></div><p className="font-mono-ui text-sm font-semibold" data-testid={`text-outstanding-${str(row.chargeId)}`}>{money(row.outstanding)} due</p></div><div className="mt-4 flex flex-wrap gap-x-5 gap-y-1 text-xs text-[hsl(var(--muted-foreground))]"><span>Charged {money(row.charged)}</span><span>Paid here {money(row.paid)}</span>{num(row.previousOutstanding) > 0 && <span>Earlier terms {money(row.previousOutstanding)}</span>}{num(row.credit) > 0 && <span>Credit {money(row.credit)}</span>}</div>{asRows(row.payments).length > 0 && <div className="mt-3 border-l-2 border-[hsl(var(--primary)/.3)] pl-3 text-xs text-[hsl(var(--muted-foreground))]">{asRows(row.payments).map((payment) => <p key={str(payment.paymentId)}>{date(payment.paidOn)} · {money(payment.amount)} · Receipt {str(payment.receiptNumber)} · {str(payment.method)}</p>)}</div>}{canManage && <div className="mt-3 flex gap-2"><Button variant="quiet" onClick={() => { setActiveCharge(str(row.chargeId)); setPaymentAmount(''); }} testId={`button-pay-charge-${str(row.chargeId)}`}>Record payment</Button><Button variant="quiet" onClick={() => { setActiveCharge(`adjust:${str(row.chargeId)}`); setAdjustmentAmount(''); }} testId={`button-adjust-charge-${str(row.chargeId)}`}>Adjustment</Button></div>}</div>)}</div> : <EmptyState icon={Landmark} title="No charges in this term" description="A new fee charge must be tied to a pupil enrolled in this year and this specific term." />}</Panel>
          {canManage && <div className="space-y-5"><Panel className="p-5">{sectionTitle('New charge', 'Charge this term', 'Category is unique per pupil and term; repeated submissions do not duplicate that charge.')}<form className="space-y-3" onSubmit={(event) => formSubmit(event, () => { const amount = Number(chargeAmount); if (!chargeEnrollment || !category.trim() || !Number.isFinite(amount) || amount < 0) return; requestConfirmation('Create term charge?', `Charge ${money(amount)} for ${category.trim()} in Term ${str(term?.number)}. This will not backfill charges or attribute previous payments.`, async () => { await execute(() => createCharge.mutateAsync({ termId, data: { enrollmentId: chargeEnrollment, category: category.trim(), amount, description: chargeDescription.trim(), idempotencyKey: freshKey() } }), 'Charge saved against this term.', () => { setChargeAmount(''); setChargeDescription(''); }); }); })}><Field label="Pupil enrollment"><select className={fieldClass} value={chargeEnrollment} onChange={(event) => setChargeEnrollment(event.target.value)} required data-testid="select-charge-enrollment"><option value="">Choose enrolled pupil</option>{enrollments.filter((item) => item.status === 'active').map((item) => <option key={str(item.id)} value={str(item.id)}>{str(item.studentName)} · {str(item.className)}</option>)}</select></Field><Field label="Category"><input className={fieldClass} value={category} onChange={(event) => setCategory(event.target.value)} required data-testid="input-charge-category" /></Field><Field label="Amount (UGX)"><input className={fieldClass} type="number" min="0" step="0.01" value={chargeAmount} onChange={(event) => setChargeAmount(event.target.value)} required data-testid="input-charge-amount" /></Field><Field label="Description (optional)"><input className={fieldClass} value={chargeDescription} onChange={(event) => setChargeDescription(event.target.value)} data-testid="input-charge-description" /></Field><Button type="submit" disabled={busy || term?.status !== 'open'} testId="button-create-term-charge">Create charge</Button>{term?.status !== 'open' && <p className="text-xs text-[hsl(var(--muted-foreground))]">Open this term before creating new charges.</p>}</form></Panel>
          {activeCharge && <Panel className="p-5">{activeCharge.startsWith('adjust:') ? <>{sectionTitle('Audited entry', 'Adjust original charge', 'An authorization reason is required and will be kept with the charge.')}<form className="space-y-3" onSubmit={(event) => formSubmit(event, () => { const amount = Number(adjustmentAmount); if (!Number.isFinite(amount) || amount <= 0 || adjustmentReason.trim().length < 3) return; requestConfirmation('Record audited adjustment?', `${adjustmentKind.replace('_', ' ')} of ${money(amount)} will be applied to this original charge. The reason will be retained.`, async () => { await execute(() => createAdjustment.mutateAsync({ chargeId: activeCharge.slice(7), data: { kind: AcademicAdjustmentInputKind[adjustmentKind], amount, reason: adjustmentReason.trim() } }), 'Adjustment recorded with its audit reason.', () => { setActiveCharge(''); setAdjustmentReason(''); }); }); })}><Field label="Type"><select className={fieldClass} value={adjustmentKind} onChange={(event) => setAdjustmentKind(event.target.value as typeof adjustmentKind)} data-testid="select-adjustment-kind">{Object.keys(AcademicAdjustmentInputKind).map((item) => <option key={item} value={item}>{item.replace('_', ' ')}</option>)}</select></Field><Field label="Amount (UGX)"><input className={fieldClass} type="number" min="0.01" step="0.01" value={adjustmentAmount} onChange={(event) => setAdjustmentAmount(event.target.value)} required data-testid="input-adjustment-amount" /></Field><Field label="Audit reason"><input className={fieldClass} minLength={3} value={adjustmentReason} onChange={(event) => setAdjustmentReason(event.target.value)} required data-testid="input-adjustment-reason" /></Field><div className="flex gap-2"><Button type="submit" disabled={busy} testId="button-save-adjustment">Record adjustment</Button><Button variant="quiet" onClick={() => setActiveCharge('')} testId="button-cancel-adjustment">Cancel</Button></div></form></> : <>{sectionTitle('Explicit allocation', 'Pay this charge', 'The payment will be attached to the selected original charge, even if it belongs to an earlier term.')}<form className="space-y-3" onSubmit={(event) => formSubmit(event, () => { const amount = Number(paymentAmount); if (!Number.isFinite(amount) || amount <= 0 || !paymentMethod.trim()) return; requestConfirmation('Record payment against this charge?', `${money(amount)} will be allocated only to this selected charge in Term ${str(term?.number)}. It will not be spread across terms.`, async () => { await execute(() => recordPayment.mutateAsync({ chargeId: activeCharge, data: { amount, method: paymentMethod.trim(), reference: paymentReference.trim(), idempotencyKey: freshKey() } }), 'Payment recorded against the selected original charge.', () => { setActiveCharge(''); setPaymentReference(''); }); }); })}><Field label="Amount (UGX)"><input className={fieldClass} type="number" min="0.01" step="0.01" value={paymentAmount} onChange={(event) => setPaymentAmount(event.target.value)} required data-testid="input-academic-payment-amount" /></Field><Field label="Method"><select className={fieldClass} value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value)} data-testid="select-academic-payment-method"><option>Cash</option><option>Mobile Money</option><option>Bank transfer</option><option>Cheque</option></select></Field><Field label="Reference (optional)"><input className={fieldClass} value={paymentReference} onChange={(event) => setPaymentReference(event.target.value)} data-testid="input-academic-payment-reference" /></Field><div className="flex gap-2"><Button type="submit" disabled={busy} testId="button-record-academic-payment">Record payment</Button><Button variant="quiet" onClick={() => setActiveCharge('')} testId="button-cancel-academic-payment">Cancel</Button></div></form></>}</Panel>}</div>}</div>}
      </div>}

      {tab === 'promotion' && <div className="grid gap-5 xl:grid-cols-[1fr_340px]"><div className="space-y-5"><Panel className="p-5 sm:p-6">{sectionTitle('Year-end review', 'Promotion decisions', 'Every active pupil must receive a reviewed decision before new-year enrollments are confirmed.')}{!year ? <EmptyState icon={GraduationCap} title="Select a source year" description="A promotion review starts from an existing academic year." /> : !cycleId ? <EmptyState icon={GraduationCap} title="Open the review" description={`Prepare or resume the review from ${str(year.year)} into ${num(year.year) + 1}. An existing cycle and its saved decisions will be reused.`} action={canManage ? <Button onClick={() => requestConfirmation('Prepare or resume promotion review?', `Use the ${str(year.year)} to ${num(year.year) + 1} review. Existing decisions will be retained if a review has already been started. No pupils move until confirmation.`, async () => { await execute(() => createCycle.mutateAsync({ data: { fromYearId: yearId, toYear: num(year.year) + 1 } }), 'Promotion review opened. Review each pupil before confirmation.', (result) => setLocalCycle(asRow(result))); })} disabled={busy} testId="button-create-promotion-cycle">Prepare or resume review</Button> : undefined} /> : decisionsQuery.isLoading ? loadingBlock : decisionsQuery.isError ? <ErrorState onRetry={() => void decisionsQuery.refetch()} /> : <div className="divide-y divide-[hsl(var(--border))]">{decisions.map((item) => { const pupil = asRow(item.student), enrollment = asRow(item.enrollment), decision = asRow(item.decision); const enrollmentId = str(enrollment.id); return <div key={enrollmentId} className="py-4" data-testid={`row-promotion-${enrollmentId}`}><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-semibold">{[pupil.firstName, pupil.middleName, pupil.lastName].filter(Boolean).join(' ')}</p><p className="text-xs text-[hsl(var(--muted-foreground))]">{str(pupil.registrationNumber)} · {str(enrollment.className)} {str(enrollment.stream)}</p></div><div className="flex items-center gap-2"><span className={`rounded-full px-2.5 py-1 text-xs font-semibold capitalize ${decision.decision === 'hold' ? 'bg-[#f6ead0] text-[#79581c]' : 'bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]'}`}>{str(decision.decision)}</span>{canManage && currentCycle.status !== 'confirmed' && <Button variant="quiet" onClick={() => { setEditingDecision(enrollmentId); setDecisionType((str(decision.decision) || 'hold') as typeof decisionType); setNextClass(str(decision.nextClassName || enrollment.className)); setNextStream(str(decision.nextStream || enrollment.stream)); setDecisionNote(str(decision.approvalNotes)); }} testId={`button-review-promotion-${enrollmentId}`}>Review <ChevronDown size={15} /></Button>}</div></div>{editingDecision === enrollmentId && canManage && <form className="mt-4 grid gap-3 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--secondary)/.45)] p-4 sm:grid-cols-2" onSubmit={(event) => formSubmit(event, () => { if (['promote', 'repeat'].includes(decisionType) && !nextClass.trim()) { setNotice({ kind: 'error', text: 'Choose the next class for a promotion or repetition.' }); return; } void execute(() => updateDecision.mutateAsync({ cycleId, enrollmentId, data: { decision: PromotionDecisionInputDecision[decisionType], ...(['promote', 'repeat'].includes(decisionType) ? { nextClassName: nextClass, nextStream } : {}), approvalNotes: decisionNote } }), 'Promotion decision saved.', () => setEditingDecision('')); })}><Field label="Decision"><select className={fieldClass} value={decisionType} onChange={(event) => setDecisionType(event.target.value as typeof decisionType)} data-testid={`select-promotion-decision-${enrollmentId}`}>{Object.keys(PromotionDecisionInputDecision).map((item) => <option value={item} key={item}>{item}</option>)}</select></Field>{['promote', 'repeat'].includes(decisionType) && <><Field label="Next class"><select className={fieldClass} value={nextClass} onChange={(event) => setNextClass(event.target.value)} required data-testid={`select-next-class-${enrollmentId}`}><option value="">Choose class</option>{classes.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Next stream"><input className={fieldClass} value={nextStream} onChange={(event) => setNextStream(event.target.value)} data-testid={`input-next-stream-${enrollmentId}`} /></Field></>}<Field label="Approval note"><input className={fieldClass} value={decisionNote} onChange={(event) => setDecisionNote(event.target.value)} data-testid={`input-promotion-note-${enrollmentId}`} /></Field><div className="flex gap-2 sm:col-span-2"><Button type="submit" disabled={busy} testId={`button-save-promotion-${enrollmentId}`}>Save decision</Button><Button variant="quiet" onClick={() => setEditingDecision('')} testId={`button-cancel-promotion-${enrollmentId}`}>Cancel</Button></div></form>}</div>; })}</div>}</Panel></div><div className="space-y-5"><Panel className="p-5">{sectionTitle('Final step', 'Confirm the cycle', 'This is the bulk write: new-year enrollments are made only for reviewed pupils.')}<p className="mb-4 text-sm text-[hsl(var(--muted-foreground))]"><strong className="text-[hsl(var(--foreground))]">{decisions.filter((item) => asRow(item.decision).decision === 'hold').length}</strong> awaiting a decision out of <strong className="text-[hsl(var(--foreground))]">{decisions.length}</strong> pupils.</p>{canManage && <Button disabled={busy || !cycleId || currentCycle.status === 'confirmed' || decisionsQuery.isLoading || !decisions.length || decisions.some((item) => asRow(item.decision).decision === 'hold')} onClick={() => requestConfirmation('Confirm all promotion decisions?', `This creates next-year enrollments for reviewed promotions and repetitions, and closes source enrollments according to all ${decisions.length} decisions. Old classes, term fees and receipts remain attached to their original records.`, async () => { await execute(() => confirmCycle.mutateAsync({ cycleId }), 'Promotion cycle confirmed. The prior year’s classes and accounts remain intact.', () => setLocalCycle((prev) => prev ? { ...prev, status: 'confirmed' } : null)); })} testId="button-confirm-promotion-cycle"><Check size={16} /> Confirm reviewed cycle</Button>}{currentCycle.status === 'confirmed' && <p className="mt-3 text-sm font-semibold text-[#3b7659]">Cycle confirmed</p>}</Panel><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--secondary)/.5)] p-5 text-sm leading-6 text-[hsl(var(--muted-foreground))]"><p className="mb-2 font-semibold text-[hsl(var(--foreground))]">Before confirming</p><p>Use “hold” while a decision needs discussion. Promotion and repetition require the next class. Transfer, withdrawal and graduation retain the pupil’s earlier enrollment and accounts.</p></div></div></div>}

      {tab === 'history' && <div className="grid gap-5 xl:grid-cols-[340px_1fr]"><Panel className="p-5">{sectionTitle('Individual record', 'Find a pupil', 'Review the enrollment, charge and payment trail across years.')}<Field label="Pupil"><select className={fieldClass} value={historyId} onChange={(event) => setHistoryId(event.target.value)} data-testid="select-history-pupil"><option value="">Choose a pupil</option>{enrollments.map((item) => <option key={str(item.id)} value={str(item.studentId)}>{str(item.studentName)} · {str(item.registrationNumber)}</option>)}</select></Field><p className="mt-3 text-xs leading-5 text-[hsl(var(--muted-foreground))]">Select the pupil from this year’s register; the history follows the same pupil profile across years.</p></Panel><Panel className="p-5 sm:p-6">{!historyId ? <EmptyState icon={History} title="A full record, not a replacement" description="Select a pupil to see how their academic journey and accounts have been preserved." /> : historyQuery.isLoading ? loadingBlock : historyQuery.isError ? <ErrorState onRetry={() => void historyQuery.refetch()} /> : <>{sectionTitle('Permanent trail', 'Academic history', 'Original records stay under the year and term where they were created.')}{(() => { const history = asRow(historyQuery.data); const records = asRows(history.enrollments); return <div className="space-y-4"><p className="text-sm text-[hsl(var(--muted-foreground))]" data-testid="text-history-pupil">Pupil: <strong className="text-[hsl(var(--foreground))]">{str(asRow(history.student).name || asRow(history.student).firstName || enrollments.find((item) => str(item.studentId) === historyId)?.studentName)}</strong></p>{records.length ? records.map((record, index) => <div key={str(record.id || index)} className="rounded-xl border border-[hsl(var(--border))] p-4" data-testid={`card-history-enrollment-${index}`}><div className="flex flex-wrap justify-between gap-2"><p className="font-semibold">{str(record.className)} {str(record.stream)}</p><span className="text-xs font-semibold capitalize text-[hsl(var(--primary))]">{str(record.status)}</span></div><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Enrolled {date(record.enrolledOn)} {record.endedOn ? ` · Ended ${date(record.endedOn)}` : ''}</p></div>) : <p className="text-sm text-[hsl(var(--muted-foreground))]">No academic enrollments recorded for this pupil yet.</p>}{Object.entries(history).filter(([key]) => !['student', 'enrollments'].includes(key)).map(([key, value]) => Array.isArray(value) && value.length ? <div key={key} className="rounded-xl bg-[hsl(var(--secondary)/.5)] p-4"><h3 className="mb-2 text-sm font-semibold capitalize">{key.replace(/([A-Z])/g, ' $1')}</h3><div className="space-y-2">{value.map((entry, index) => { const row = asRow(entry); return <p className="text-xs leading-5 text-[hsl(var(--muted-foreground))]" key={index}>{[row.year, row.number ? `Term ${str(row.number)}` : null, row.category, row.kind, row.decision, row.amount != null ? money(row.amount) : null, row.receiptNumber].filter(Boolean).join(' · ') || `${key} record ${index + 1}`}</p>; })}</div></div> : null)}</div>; })()}</>}</Panel></div>}
    </>}
    {pending && <ConfirmDialog title={pending.title} description={pending.description} busy={busy} onCancel={() => setPending(null)} onConfirm={() => { const action = pending.action; setPending(null); void action(); }} />}
  </div></AppShell>;
}